class WordList extends Array {
  longest() {
    return this.reduce((a, b) => (b.length > a.length ? b : a), "");
  }
}

const words = WordList.from(["cat", "horse", "ant"]);
const long = words.filter((w) => w.length > 3);

console.log(words instanceof WordList);
console.log(long instanceof WordList);
console.log(long.longest());
